import http from 'node:http';

const pesanan = [];
async function bacaBody(req) {
  let isi = '';
  for await (const potongan of req) isi += potongan;
  return isi;
}
function kirimJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}
const server = http.createServer(async (req, res) => {
  if (req.method !== 'POST') return kirimJson(res, 405, { error: 'Hanya POST' });
  let data;
  try {
    data = JSON.parse(await bacaBody(req));
  } catch {
    return kirimJson(res, 400, { error: 'Body bukan JSON yang sah' });
  }
  if (typeof data.menu !== 'string' || !Number.isInteger(data.jumlah) || data.jumlah < 1) {
    return kirimJson(res, 400, { error: 'menu (teks) dan jumlah (bilangan bulat >= 1) wajib' });
  }
  const baru = { id: pesanan.length + 1, menu: data.menu, jumlah: data.jumlah };
  pesanan.push(baru);
  kirimJson(res, 201, baru);
});
server.listen(3000);

const kirim = (body) => fetch('http://localhost:3000/pesanan', {
  method: 'POST', headers: { 'Content-Type': 'application/json' }, body,
});
let r = await kirim(JSON.stringify({ menu: 'Kopi', jumlah: 2 }));
console.log(r.status, await r.json());
r = await kirim('{ menu: Kopi }');
console.log(r.status, await r.json());
r = await kirim(JSON.stringify({ menu: 'Teh', jumlah: 0 }));
console.log(r.status, (await r.json()).error);
server.close();

